/**
 * Independent P1-05 security/load gate. No fixtures in the deployed API.
 * Starts a short-lived API on a random loopback port and uses synthetic
 * records in the dedicated Apartment DEV database. Cleanup is scoped to IDs
 * generated by this script; existing tenant, invoice and LINE data untouched.
 */
import {spawn} from "node:child_process";
import {randomUUID} from "node:crypto";
import {createServer} from "node:net";
import {strict as assert} from "node:assert";
import {and,eq,inArray} from "drizzle-orm";
import {db,sqlClient} from "../src/db/client.js";
import {auditLogs,memberships,meterReadings,organizations,properties,
 propertyStaffGrants,rooms,sessions,users} from "../src/db/schema.js";
import {newSessionToken,tokenHash} from "../src/security.js";

async function freeLoopbackPort():Promise<number>{
 const server=createServer();
 return new Promise((resolve,reject)=>{
  server.once("error",reject);
  server.listen(0,"127.0.0.1",()=>{
   const address=server.address();
   if(typeof address==="string"||!address){server.close();reject(new Error("NO_PORT"));return;}
   server.close(error=>error?reject(error):resolve(address.port));
  });
 });
}
const port=await freeLoopbackPort();
const base="http://127.0.0.1:"+port;
const tag=randomUUID().slice(0,8);
const tracked={users:[] as string[],sessions:[] as string[],
 orgs:[] as string[],properties:[] as string[],rooms:[] as string[]};
const child=spawn("node",["--import","tsx","src/index.ts"],{
 cwd:process.cwd(),stdio:"ignore",env:{...process.env,HOST:"127.0.0.1",PORT:String(port)}
});
const latency:number[]=[];
type Result={status:number;body:any;durationMs:number};
async function req(path:string,token:string,method="GET",body?:unknown,origin?:string):Promise<Result>{
 const start=performance.now();
 const response=await fetch(base+path,{method,headers:{
  ...(token?{cookie:"apartment_session="+token}:{}),
  ...(body===undefined?{}:{"content-type":"application/json"}),
  ...(origin?{origin}:{})
 },...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(12_000)});
 const durationMs=performance.now()-start;
 latency.push(durationMs);
 return {status:response.status,body:await response.json(),durationMs};
}
function percentile(n:number){
 const a=[...latency].sort((x,y)=>x-y);
 return Math.round(a[Math.max(0,Math.ceil(a.length*n)-1)]??0);
}
async function actor(label:string){
 const [u]=await db.insert(users).values({
  lineSubject:"independent-p105-"+label+"-"+tag,displayName:"QA "+label+" "+tag
 }).returning();
 tracked.users.push(u.id);
 const token=newSessionToken();
 const [s]=await db.insert(sessions).values({userId:u.id,tokenHash:tokenHash(token),
  expiresAt:new Date(Date.now()+180_000)}).returning();
 tracked.sessions.push(s.id);
 return {id:u.id,token,sessionId:s.id};
}
async function ready(){
 const deadline=Date.now()+10_000;
 while(Date.now()<deadline){
  if(child.exitCode!==null)throw new Error("ISOLATED_API_EXITED");
  try{if((await fetch(base+"/readyz",{signal:AbortSignal.timeout(1000)})).ok)return;}catch{}
  await new Promise(r=>setTimeout(r,150));
 }
 throw new Error("ISOLATED_API_NOT_READY");
}
async function test(){
 await ready();
 const owner=await actor("owner"),staff=await actor("staff"),stranger=await actor("stranger");
 const [orgA,orgB]=await db.insert(organizations).values([
  {name:"QA P105 A "+tag},{name:"QA P105 B "+tag}]).returning();
 tracked.orgs.push(orgA.id,orgB.id);
 await db.insert(memberships).values([
  {organizationId:orgA.id,userId:owner.id,role:"OWNER"},
  {organizationId:orgA.id,userId:staff.id,role:"STAFF"}]);
 const defaults={rentSatang:10000,waterSatangPerUnit:100,electricSatangPerUnit:200};
 const [a,other,b]=await db.insert(properties).values([
  {organizationId:orgA.id,name:"QA allowed",...defaults},
  {organizationId:orgA.id,name:"QA unassigned",...defaults},
  {organizationId:orgB.id,name:"QA foreign",...defaults}]).returning();
 tracked.properties.push(a.id,other.id,b.id);
 const [room]=await db.insert(rooms).values({organizationId:orgA.id,
  propertyId:a.id,number:"QA01"}).returning();
 tracked.rooms.push(room.id);
 await db.insert(propertyStaffGrants).values({organizationId:orgA.id,propertyId:a.id,
  userId:staff.id,level:"METER_READER",updatedBy:owner.id});
 const roomsPath="/v1/properties/"+a.id+"/rooms";
 const meterPath="/v1/properties/"+a.id+"/readings";
 const revokePath="/v1/organizations/"+orgA.id+"/staff/members/"+staff.id+"/revoke";
 const allowed=await req(roomsPath,staff.token);
 assert.equal(allowed.status,200,"assigned staff must read allowed rooms");
 assert.equal(allowed.body.length,1);
 assert.equal("rentOverrideSatang" in allowed.body[0],false,"no rate metadata");
 for(const id of [other.id,b.id]){
  const denied=await req("/v1/properties/"+id+"/rooms",staff.token);
  assert.equal(denied.status,403,"cross-property access "+id);
 }
 for(const path of ["/leases","/invoices","/overview"]){
  const r=await req("/v1/properties/"+a.id+path,staff.token);
  assert.equal(r.status,403,"staff must not see finance/tenant "+path);
 }
 assert.equal((await req("/v1/properties/"+a.id+"/bills/preview",staff.token,
  "POST",{roomId:room.id,start:"2026-10-01",endExclusive:"2026-11-01"})).status,403);
 assert.equal((await req(roomsPath,"")).status,401);
 assert.equal((await req(roomsPath,"forged-session-token")).status,401);
 assert.equal((await req(meterPath,staff.token,"POST",{
  roomId:room.id,kind:"WATER",readAt:"2026-10-01",value:"10.000"
 },"https://untrusted.invalid")).status,403);
 for(const value of ["-1.000","1.0000","123456789012","nan"]){
  assert.equal((await req(meterPath,staff.token,"POST",{
   roomId:room.id,kind:"WATER",readAt:"2026-10-01",value
  })).status,400,"invalid meter reading "+value);
 }
 const first=await req(meterPath,staff.token,"POST",{
  roomId:room.id,kind:"WATER",readAt:"2026-10-01",value:"10.000"});
 assert.equal(first.status,201,JSON.stringify(first.body));
 const duplicateBody={roomId:room.id,kind:"WATER",readAt:"2026-10-02",value:"10.100"};
 const duplicates=await Promise.all(Array.from({length:16},
  ()=>req(meterPath,staff.token,"POST",duplicateBody)));
 const counts=(n:number)=>duplicates.filter(r=>r.status===n).length;
 assert.equal(counts(201),1,"exactly one meter write wins");
 assert.equal(counts(409),15,"other identical requests must conflict, not 500");
 const stored=await db.select({id:meterReadings.id}).from(meterReadings)
  .where(and(eq(meterReadings.organizationId,orgA.id),eq(meterReadings.roomId,room.id)));
 assert.equal(stored.length,2,"no duplicate meter rows");
 // A bounded mixed 48-request concurrent read burst, lower than 90/min global per-IP cap.
 const paths=Array.from({length:48},(_,i)=>
  i%4===0?"/v1/properties/"+other.id+"/rooms":
  i%4===1?"/v1/properties/"+b.id+"/rooms":roomsPath);
 const began=performance.now();
 const burst=await Promise.all(paths.map(path=>req(path,staff.token)));
 const elapsed=Math.round(performance.now()-began);
 for(let i=0;i<burst.length;i++){
  const want=paths[i]===roomsPath?200:403;
  assert.equal(burst[i].status,want,"mixed tenant scope burst #"+i);
 }
 const after=await req(revokePath,owner.token,"POST",{propertyId:a.id});
 assert.equal(after.status,200,JSON.stringify(after.body));
 const afterRevoke=await Promise.all(Array.from({length:5},
  (_,i)=>req(meterPath,staff.token,"POST",{...duplicateBody,
   readAt:"2026-10-"+String(i+3).padStart(2,"0"),value:"11.000"})));
 assert.ok(afterRevoke.every(r=>r.status===403),"revoke must deny new writes");
 assert.equal((await req(roomsPath,staff.token)).status,403);
 await db.update(sessions).set({revokedAt:new Date()}).where(eq(sessions.id,stranger.sessionId));
 assert.equal((await req("/v1/me",stranger.token)).status,401,"revoked session reused");
 await db.update(users).set({status:"DISABLED"}).where(eq(users.id,owner.id));
 assert.equal((await req("/v1/me",owner.token)).status,401,"disabled account reused");
 console.log(JSON.stringify({result:"PASS",suite:"P1-05 independent QA",
  mixedBurstRequests:48,duplicateWrites:16,duplicateSuccess:counts(201),
  duplicateConflict:counts(409),deniedAfterRevoke:afterRevoke.length,
  burstElapsedMs:elapsed,overallP50Ms:percentile(.5),overallP95Ms:percentile(.95),
  peakConcurrency:48,source:"isolated loopback API + synthetic DEV DB",
  lineMessagesSent:0}));
}
async function cleanup(){
 child.kill("SIGTERM");
 // Delete only records created by this test, in FK order.
 if(tracked.orgs.length){
  await db.delete(propertyStaffGrants).where(inArray(propertyStaffGrants.organizationId,tracked.orgs));
  await db.delete(auditLogs).where(inArray(auditLogs.organizationId,tracked.orgs));
 }
 if(tracked.rooms.length)await db.delete(meterReadings).where(inArray(meterReadings.roomId,tracked.rooms));
 if(tracked.rooms.length)await db.delete(rooms).where(inArray(rooms.id,tracked.rooms));
 if(tracked.properties.length)await db.delete(properties).where(inArray(properties.id,tracked.properties));
 if(tracked.orgs.length){
  await db.delete(memberships).where(inArray(memberships.organizationId,tracked.orgs));
  await db.delete(organizations).where(inArray(organizations.id,tracked.orgs));
 }
 if(tracked.sessions.length)await db.delete(sessions).where(inArray(sessions.id,tracked.sessions));
 if(tracked.users.length)await db.delete(users).where(inArray(users.id,tracked.users));
 await sqlClient.end();
}
try{await test();}finally{await cleanup();}
